let db = (() => { if (new URLSearchParams(location.search).has('novo')) localStorage.removeItem(CHAVE); try { return JSON.parse(localStorage.getItem(CHAVE)) || gerar(); } catch { return gerar(); } })();
['contas', 'descontos', 'base', 'perdas', 'fotos'].forEach((k) => { if (!Array.isArray(db[k])) db[k] = []; }); db.alcada ??= 10; db.acel ??= 1.5; db.pessoas.filter((p) => p.papel === 'Closer').forEach((p) => { p.cota ??= 400000; p.ganho ??= 0; p.com ??= 8; });
window.veltriaDados = () => db; // modo conta: começar do zero e resumo para a IA
const guarda = () => { try { localStorage.setItem(CHAVE, JSON.stringify(db)); } catch { toque('Sem espaço no navegador.'); } };
const regist = (o) => { db.audit.unshift({ q: agora(), quem: 'Você (diretor comercial)', o }); db.audit = db.audit.slice(0, 50); };
const pessoa = (id) => db.pessoas.find((p) => p.id === id) || { nome: '—' };
const pontos = (l) => db.regras.filter((r) => l.sinais.includes(r.k)).reduce((s, r) => s + r.pts, 0);
const quando = (d) => { const x = new Date(); x.setDate(x.getDate() + d); return x.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }); };
const closers = () => db.pessoas.filter((p) => p.papel === 'Closer');
const comissao = (p) => { const exc = Math.max(0, p.ganho - p.cota); return (p.ganho * p.com / 100) + exc * p.com / 100 * (db.acel - 1); };
const problemas = (d) => [d.prox == null ? 'sem próximo passo' : d.prox < 0 ? `próximo passo atrasado ${-d.prox} dia(s)` : '', d.parado >= (db.paradoLim ?? 14) ? `parado há ${d.parado} dias` : '', d.cat === 'commit' && meddic(d) < 4 ? `commit com qualificação fraca (${meddic(d)}/6)` : '', d.fecha < 0 ? 'data de fechamento passou' : ''].filter(Boolean);
const PAPEIS = { decisor: ['Decisor', 'ok'], campeao: ['Campeão', 'ag'], influenciador: ['Influenciador', ''], bloqueador: ['Bloqueador', 'at'] };
// planilha para o Excel (separador ;); célula que começa com = + - @ vira texto
function baixaCSV(nome, linhas) { const t = '﻿' + linhas.map((l) => l.map((v) => { const s1 = String(v ?? ''); return `"${(/^[=+\-@]/.test(s1) && typeof v !== 'number' ? `'${s1}` : s1).replace(/"/g, '""')}"`; }).join(';')).join('\r\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([t], { type: 'text/csv;charset=utf-8' })); a.download = nome; document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 2000); }
function form(t, campos, ok, fn) { quadro(`<h2>${t}</h2><form>${campos}<p class="erro-f" hidden style="color:#a5503f;font-size:.86rem"></p><div class="pe"><button type="button" class="bt" data-sair>Cancelar</button><button class="bt p">${ok}</button></div></form>`, (q, fecha) => q.querySelector('form').addEventListener('submit', (ev) => { ev.preventDefault(); const r = fn(new FormData(ev.target)); if (typeof r === 'string') { const er = q.querySelector('.erro-f'); er.textContent = r; er.hidden = false; return; } guarda(); fecha(); render(); })); }
const soma = (cat) => db.deals.filter((d) => d.cat === cat).reduce((s, d) => s + d.valor, 0);

function toque(t) { const a = document.createElement('div'); a.textContent = t; $('#toques').append(a); setTimeout(() => a.remove(), 3300); }
function quadro(html, liga) {
  const v = document.createElement('div'); v.className = 'cortina'; v.innerHTML = `<div class="quadro-m" role="dialog" aria-modal="true">${html}</div>`;
  const ant = document.activeElement; document.body.append(v);
  const fecha = () => { v.remove(); ant?.focus?.(); };
  v.addEventListener('click', (ev) => { if (ev.target === v || ev.target.closest('[data-sair]')) fecha(); });
  v.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') fecha(); });
  setTimeout(() => (v.querySelector('input, select') || v.querySelector('button'))?.focus(), 30);
  liga?.(v.querySelector('.quadro-m'), fecha);
}

