const MOD = [['previsao', 'Previsão'], ['higiene', 'Higiene do pipeline'], ['contas', 'Contas e decisores'], ['cadencias', 'Cadências'], ['pontuacao', 'Pontuação de leads'], ['distribuicao', 'Distribuição'], ['descontos', 'Descontos'], ['renovacoes', 'Renovações'], ['ganhos', 'Ganhos e perdas'], ['times', 'Times'], ['playbook', 'Playbook'], ['auditoria', 'Auditoria'], ['equipe', 'Equipe'], ['ajustes', 'Ajustes']];
const M = {
  previsao() {
    const c = soma('commit'), m = soma('melhor'), p = soma('pipeline'), W = 760, H = 240, sem = 13, hoje = 7, x = (i) => 40 + i / sem * (W - 60), y = (v) => H - 24 - v / (db.meta * 1.25) * (H - 40);
    const real = Array.from({ length: hoje + 1 }, (_, i) => db.realizado * (i / hoje) ** 1.1), bx = x(hoje), fimBaixo = db.realizado + c, fimAlto = db.realizado + c + m;
    return `<div class="titulo"><div><h1>Previsão do trimestre</h1><p>Meta de ${R$(db.meta)}. Cada closer classifica os negócios: commit (fecha com certeza), melhor caso e pipeline. O cone mostra onde o trimestre termina.</p></div><div class="bar"><button class="bt" data-a="exportar">Baixar planilha</button><button class="bt" data-a="foto">Fechar a semana</button><button class="bt p" data-a="novo-deal">+ Negócio</button></div></div>${(() => { const f = db.fotos.at(-1); if (!f) return ''; const dc = (c + db.realizado) - (f.commit + f.realizado), dm = m - f.melhor; return `<p class="cx" style="margin:0 0 14px;padding:10px 14px">Desde a foto da semana ${f.sem}: realizado + commit <b class="${dc >= 0 ? 'bom' : 'mau'}">${dc >= 0 ? '+' : '−'}${k$(Math.abs(dc))}</b> · melhor caso <b>${dm >= 0 ? '+' : '−'}${k$(Math.abs(dm))}</b> · pipeline <b>${p - f.pipeline >= 0 ? '+' : '−'}${k$(Math.abs(p - f.pipeline))}</b></p>`; })()}
      <div class="grade" style="margin-bottom:14px"><div class="cx k3 ind"><small>Realizado</small><b>${k$(db.realizado)}</b><span>${Math.round(db.realizado / db.meta * 100)}% da meta</span></div><div class="cx k3 ind"><small>Realizado + commit</small><b class="${fimBaixo >= db.meta ? 'bom' : 'mau'}">${k$(fimBaixo)}</b><span>${fimBaixo >= db.meta ? 'meta garantida' : `faltam ${k$(db.meta - fimBaixo)}`}</span></div><div class="cx k3 ind"><small>Com melhor caso</small><b>${k$(fimAlto)}</b><span>${Math.round(fimAlto / db.meta * 100)}% da meta</span></div><div class="cx k3 ind"><small>Pipeline restante</small><b>${k$(p)}</b><span>cobertura ${(p + m + c) / Math.max(1, db.meta - db.realizado) >= 3 ? 'boa' : 'baixa'}: ${((p + m + c) / Math.max(1, db.meta - db.realizado)).toFixed(1).replace('.', ',')}×</span></div></div>
      <div class="grade"><section class="cx k7"><h2>Cone do trimestre <small>· semanas</small></h2><svg class="cone" viewBox="0 0 ${W} ${H}" role="img" aria-label="Realizado e projeção contra a meta">
        <line x1="40" x2="${W - 20}" y1="${y(db.meta)}" y2="${y(db.meta)}" stroke="#a5503f" stroke-dasharray="5 4"/><text x="${W - 20}" y="${y(db.meta) - 6}" text-anchor="end">meta ${k$(db.meta)}</text>
        <path d="M${bx},${y(db.realizado)} L${x(sem)},${y(fimAlto)} L${x(sem)},${y(fimBaixo)} Z" fill="#83a8a0" opacity=".35"/>
        <line x1="${bx}" y1="${y(db.realizado)}" x2="${x(sem)}" y2="${y(fimBaixo)}" stroke="#215a60" stroke-width="2" stroke-dasharray="4 3"/><line x1="${bx}" y1="${y(db.realizado)}" x2="${x(sem)}" y2="${y(fimAlto)}" stroke="#83a8a0" stroke-width="2" stroke-dasharray="4 3"/>
        <polyline fill="none" stroke="#16454a" stroke-width="3" points="${real.map((v, i) => `${x(i)},${y(v)}`).join(' ')}"/><circle cx="${bx}" cy="${y(db.realizado)}" r="4" fill="#16454a"/>
        ${Array.from({ length: sem + 1 }, (_, i) => (i % 2 ? '' : `<text x="${x(i)}" y="${H - 6}" text-anchor="middle">S${i}</text>`)).join('')}</svg>
        <div class="legenda"><span style="--c:#16454a">realizado</span><span style="--c:#215a60">só commit</span><span style="--c:#83a8a0">com melhor caso</span><span style="--c:#a5503f">meta</span></div></section>
      <section class="cx k5 rolo"><h2>Negócios do trimestre</h2><table><thead><tr><th>Conta</th><th class="dir">Valor</th><th>Mês</th><th>Categoria</th></tr></thead><tbody>${[...db.deals].sort((a, b) => b.valor - a.valor).map((d) => `<tr><td><b>${e(d.conta)}</b>${problemas(d).length ? ' <span class="tag at" title="' + e(problemas(d).join(', ')) + '">!</span>' : ''}<br><small style="color:var(--tx-3)">${e(pessoa(d.dono).nome)} · ${d.prob}%</small><br><button class="bt x" data-a="editar-deal" data-id="${d.id}">Editar</button> <button class="bt x" data-a="perder" data-id="${d.id}">Perdido</button></td><td class="dir">${k$(d.valor)}</td><td>${d.mes}</td><td><select class="cat" data-cat="${d.id}" aria-label="Categoria de ${e(d.conta)}">${[['commit', 'commit'], ['melhor', 'melhor caso'], ['pipeline', 'pipeline'], ['ganho', 'ganho']].map(([v, t]) => `<option value="${v}" ${d.cat === v ? 'selected' : ''}>${t}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></section></div>`;
  },
  higiene() {
    const l = db.deals.map((d) => ({ d, p: problemas(d) })).filter((x) => x.p.length).sort((a, b) => b.d.valor - a.d.valor), total = l.reduce((t, x) => t + x.d.valor, 0);
    return `<div class="titulo"><div><h1>Higiene do pipeline</h1><p>Negócio sem próximo passo, com o passo atrasado, parado há 14 dias ou com a data de fechamento vencida distorce a previsão. Arrume antes da reunião de segunda.</p></div></div>
      <div class="grade" style="margin-bottom:14px"><div class="cx k4 ind"><small>Negócios com problema</small><b class="${l.length ? 'mau' : 'bom'}">${l.length} de ${db.deals.length}</b><span>${k$(total)} em jogo</span></div><div class="cx k4 ind"><small>Sem próximo passo</small><b>${db.deals.filter((d) => d.prox == null).length}</b><span>ninguém sabe o que fazer</span></div><div class="cx k4 ind"><small>Commit com problema</small><b class="${l.some((x) => x.d.cat === 'commit') ? 'mau' : ''}">${l.filter((x) => x.d.cat === 'commit').length}</b><span>commit precisa estar limpo</span></div></div>
      <section class="cx rolo"><table><thead><tr><th>Conta</th><th>Closer</th><th>Categoria</th><th class="dir">Valor</th><th>Problema</th><th></th></tr></thead><tbody>${l.map(({ d, p }) => `<tr><td><b>${e(d.conta)}</b></td><td>${e(pessoa(d.dono).nome)}</td><td><span class="tag ${d.cat === 'commit' ? 'ag' : ''}">${d.cat === 'melhor' ? 'melhor caso' : d.cat}</span></td><td class="dir">${k$(d.valor)}</td><td>${p.map((x) => `<span class="tag at">${x}</span>`).join(' ')}</td><td><button class="bt x a" data-a="proximo" data-id="${d.id}">Marcar próximo passo</button></td></tr>`).join('') || '<tr><td colspan="6">Pipeline limpo.</td></tr>'}</tbody></table></section>`;
  },
  contas() {
    return `<div class="titulo"><div><h1>Contas e decisores</h1><p>Venda grande se ganha com várias pessoas. Mapeie quem decide, quem defende você por dentro (campeão) e quem pode travar.</p></div><button class="bt p" data-a="nova-conta">+ Conta</button></div>
      <div class="grade">${db.contas.map((c) => { const ds = db.deals.filter((d) => sa(d.conta) === sa(c.nome)), sem = []; if (!c.contatos.some((x) => x.papel === 'decisor')) sem.push('sem decisor mapeado'); if (!c.contatos.some((x) => x.papel === 'campeao')) sem.push('sem campeão'); if (c.contatos.some((x) => x.papel === 'decisor' && x.engaj === 'baixo')) sem.push('decisor pouco engajado'); return `<section class="cx k6"><h2 style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><span>${e(c.nome)} <small>· ${e(c.seg)}${ds.length ? ` · ${k$(ds.reduce((t, d) => t + d.valor, 0))} em negócio` : ''}</small></span><button class="bt x" data-a="novo-contato" data-id="${c.id}">+ Pessoa</button></h2>${sem.length ? `<p style="margin:0 0 8px">${sem.map((x) => `<span class="tag at">${x}</span>`).join(' ')}</p>` : '<p style="margin:0 0 8px"><span class="tag ok">mapa completo</span></p>'}<table><tbody>${c.contatos.map((x) => `<tr><td><b>${e(x.nome)}</b><br><small style="color:var(--tx-3)">${e(x.cargo)}</small></td><td><span class="tag ${PAPEIS[x.papel][1]}">${PAPEIS[x.papel][0]}</span></td><td><select class="cat" data-engaj="${c.id}|${x.id}" aria-label="Engajamento de ${e(x.nome)}">${[['alto', 'engajado'], ['medio', 'morno'], ['baixo', 'distante']].map(([v, t]) => `<option value="${v}" ${x.engaj === v ? 'selected' : ''}>${t}</option>`).join('')}</select></td></tr>`).join('') || '<tr><td>Ninguém mapeado.</td></tr>'}</tbody></table></section>`; }).join('') || '<section class="cx k12"><p>Nenhuma conta mapeada.</p></section>'}</div>`;
  },
  descontos() {
    const pend = db.descontos.filter((x) => x.st === 'pendente'), feitos = db.descontos.filter((x) => x.st !== 'pendente').slice(-10).reverse();
    return `<div class="titulo"><div><h1>Descontos</h1><p>Closer dá até ${db.alcada}% sozinho. Acima disso, o pedido vem para você com o motivo, e o valor do negócio só muda depois da aprovação.</p></div><div class="bar"><label class="cp" style="margin:0">Alçada do closer (%)<input type="number" data-alcada min="0" max="50" value="${db.alcada}" style="width:80px"></label><button class="bt p" data-a="pedir-desc">+ Pedido</button></div></div>
      <div class="grade"><section class="cx k7"><h2>Esperando você</h2><table><tbody>${pend.map((x) => { const d = db.deals.find((y) => y.conta === x.conta); return `<tr><td><b>${e(x.conta)}</b> · <b>${x.pct}%</b>${d ? ` <small style="color:var(--tx-3)">(${k$(d.valor)} → ${k$(d.valor * (1 - x.pct / 100))})</small>` : ''}<br><small style="color:var(--tx-3)">${e(pessoa(x.quem).nome)} · “${e(x.motivo)}”</small></td><td class="dir" style="white-space:nowrap"><button class="bt x" data-a="nega-desc" data-id="${x.id}">Negar</button> <button class="bt x a" data-a="aprova-desc" data-id="${x.id}">Aprovar</button></td></tr>`; }).join('') || '<tr><td>Nada esperando.</td></tr>'}</tbody></table></section>
      <section class="cx k5"><h2>Decididos</h2><table><tbody>${feitos.map((x) => `<tr><td>${e(x.conta)} · ${x.pct}%</td><td><span class="tag ${x.st === 'aprovado' ? 'ok' : 'at'}">${x.st}</span></td></tr>`).join('') || '<tr><td>Nenhum ainda.</td></tr>'}</tbody></table></section></div>`;
  },
  renovacoes() {
    const l = [...db.base].sort((a, b) => a.renova - b.renova), mrr = l.reduce((t, x) => t + x.mrr, 0), em90 = l.filter((x) => x.renova <= 90), risco = l.filter((x) => x.saude === 'vermelho' || (x.saude === 'amarelo' && x.renova <= 30));
    return `<div class="titulo"><div><h1>Renovações e expansão</h1><p>Clientes da base: quando renovam, como estão usando e quanto dá para crescer em cada um. Cliente com uso baixo perto da renovação é risco de cancelamento.</p></div></div>
      <div class="grade" style="margin-bottom:14px"><div class="cx k4 ind"><small>Receita mensal da base</small><b>${k$(mrr)}</b><span>${l.length} clientes</span></div><div class="cx k4 ind"><small>Renova em 90 dias</small><b>${k$(em90.reduce((t, x) => t + x.mrr, 0))}/mês</b><span>${em90.length} contratos</span></div><div class="cx k4 ind"><small>Em risco</small><b class="${risco.length ? 'mau' : 'bom'}">${risco.length}</b><span>${k$(risco.reduce((t, x) => t + x.mrr * 12, 0))} por ano</span></div></div>
      <section class="cx rolo"><table><thead><tr><th>Cliente</th><th class="dir">Mensal</th><th>Renova</th><th>Saúde</th><th class="dir">Uso</th><th class="dir">Pode crescer</th><th></th></tr></thead><tbody>${l.map((x) => `<tr><td><b>${e(x.conta)}</b></td><td class="dir">${R$(x.mrr)}</td><td>${x.renova < 0 ? `<span class="tag at">venceu ${quando(x.renova)}</span>` : `${quando(x.renova)} <small style="color:var(--tx-3)">(${x.renova} d)</small>`}</td><td><span class="tag ${x.saude === 'verde' ? 'ok' : 'at'}">${{ verde: 'saudável', amarelo: 'atenção', vermelho: 'risco' }[x.saude]}</span></td><td class="dir">${Math.round(x.uso * 100)}%</td><td class="dir">${x.expansao ? `${R$(x.expansao)}/mês` : '—'}</td><td style="white-space:nowrap"><button class="bt x" data-a="renovado" data-id="${x.id}">Renovou</button>${x.expansao ? ` <button class="bt x a" data-a="expandir" data-id="${x.id}">Abrir expansão</button>` : ''}</td></tr>`).join('')}</tbody></table></section>`;
  },
  cadencias() {
    const minha = db.fila;
    return `<div class="titulo"><div><h1>Cadências</h1><p>Sequências de toques em vários canais. A taxa de cada passo mostra onde o lead responde e onde a cadência morre.</p></div><button class="bt p" data-a="nova-cad">+ Cadência</button></div>
      ${db.cadencias.map((c) => `<section class="cx" style="margin-bottom:14px"><h2 style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><span>${e(c.nome)} <small>· ${c.leads} leads dentro</small></span><button class="bt x" data-a="editar-cad" data-id="${c.id}">Editar passos</button></h2><div class="etapas-c" style="--n:${c.passos.length}">${c.passos.map(([d, canal, t, tx]) => `<div class="etapa-c"><small>${d} · ${canal}</small><b>${e(t)}</b><span class="tx">${Math.round(tx * 100)}% respondem</span></div>`).join('')}</div></section>`).join('')}
      <section class="cx"><h2>Fila dos SDRs hoje <small>· gerada pelas cadências</small></h2><table><tbody>${minha.map((f) => `<tr><td><input type="checkbox" data-fila="${f.id}" ${f.feito ? 'checked' : ''} style="width:18px;height:18px;accent-color:var(--pt)" aria-label="Feito"></td><td>${f.feito ? `<s style="color:var(--tx-3)">${e(f.t)}</s>` : e(f.t)}</td><td><span class="tag ag">${f.canal}</span></td><td>${e(pessoa(f.dono).nome)}</td></tr>`).join('')}</tbody></table></section>`;
  },
  pontuacao() {
    const l = db.leads.map((x) => ({ ...x, p: pontos(x) })).sort((a, b) => (a.st === 'desq') - (b.st === 'desq') || b.p - a.p);
    return `<div class="titulo"><div><h1>Pontuação de leads</h1><p>Cada sinal vale pontos. Acima de <b>${db.corte}</b> o lead está quente e vai direto para um closer; abaixo, continua na cadência do SDR.</p></div><div class="bar"><label class="cp" style="margin:0">Corte<input type="number" data-corte value="${db.corte}" style="width:80px"></label><button class="bt p" data-a="novo-lead">+ Lead</button></div></div>
      <div class="grade"><section class="cx k5"><h2>Regras</h2><table><tbody>${db.regras.map((r) => `<tr><td>${e(r.nome)}</td><td class="dir"><input class="peso" data-peso="${r.k}" value="${r.pts}" aria-label="Pontos de ${e(r.nome)}"></td></tr>`).join('')}</tbody></table></section>
      <section class="cx k7 rolo"><h2>Leads</h2><table><thead><tr><th class="dir">Pontos</th><th>Lead</th><th>Empresa</th><th></th></tr></thead><tbody>${l.map((x) => `<tr><td class="dir"><span class="pontos" style="--c:${x.p >= db.corte ? '#3f7a5e' : x.p >= db.corte * 0.6 ? '#b88a35' : '#6d7e83'}">${x.p}</span></td><td><b>${e(x.nome)}</b><br><small style="color:var(--tx-3)">${e(x.cargo)}</small></td><td>${e(x.empresa)}</td><td>${x.st === 'closer' ? '<span class="tag ok">com closer</span>' : x.st === 'desq' ? `<span class="tag at" title="${e(x.motivo || '')}">desqualificado</span>` : x.p >= db.corte ? `<button class="bt x a" data-a="passar" data-id="${x.id}">Passar para closer</button>` : `<span class="tag">na cadência</span> <button class="bt x" data-a="desq" data-id="${x.id}">Desqualificar</button>`}</td></tr>`).join('')}</tbody></table></section></div>`;
  },
  distribuicao() {
    const sdrs = db.pessoas.filter((p) => p.papel === 'SDR');
    return `<div class="titulo"><div><h1>Distribuição de leads</h1><p>Lead novo cai na fila e o sistema entrega para alguém na hora. Prazo de primeiro contato: ${db.sla} minutos. Depois disso, passa para o próximo da fila.</p></div><button class="bt p" data-a="distribuir" ${db.novos.some((n) => !n.para) ? '' : 'disabled'}>Distribuir agora</button></div>
      <div class="grade"><section class="cx k4"><h2>Regra</h2>${[['rodizio', 'Rodízio', 'um para cada, na ordem'], ['territorio', 'Território', 'pelo estado do lead'], ['porte', 'Porte', 'empresa grande vai para o SDR sênior']].map(([k, n, d]) => `<label class="chave" style="display:flex;padding:6px 0"><input type="radio" name="modo" data-modo="${k}" ${db.modo === k ? 'checked' : ''}><span><b>${n}</b><br><small style="color:var(--tx-3)">${d}</small></span></label>`).join('')}<label class="cp" style="margin-top:10px">Prazo de primeiro contato (min)<input type="number" data-sla value="${db.sla}"></label></section>
      <section class="cx k8 rolo"><h2>Fila de entrada</h2><table><thead><tr><th>Empresa</th><th>UF</th><th class="dir">Funcionários</th><th>Para</th></tr></thead><tbody>${db.novos.map((n) => `<tr><td><b>${e(n.empresa)}</b></td><td>${n.uf}</td><td class="dir">${n.func}</td><td>${n.para ? `<span class="tag ok">${e(pessoa(n.para).nome)}</span>` : '<span class="tag at">aguardando</span>'}</td></tr>`).join('')}</tbody></table>
        <h2 style="margin-top:16px">Tempo de primeiro contato</h2><div class="barras">${sdrs.map((s, i) => { const m = [7, 22, 11][i]; return `<div class="l"><span>${e(s.nome)} · ${e(s.area)}</span><span class="t"><i style="width:${Math.min(100, m / 30 * 100)}%;--c:${m > db.sla ? '#a5503f' : '#3f7a5e'}"></i></span><b class="dir">${m} min</b></div>`; }).join('')}</div></section></div>`;
  },
  ganhos() {
    const motivos = [['Preço acima do orçamento', 14, 'mau'], ['Escolheu concorrente (Contaflux)', 9, 'mau'], ['Sem decisor na conversa', 7, 'mau'], ['Timing: projeto adiado', 6, 'at']], venc = [['Integração com o ERP', 18], ['Atendimento na implantação', 15], ['Relatórios prontos', 11]];
    return `<div class="titulo"><div><h1>Ganhos e perdas</h1><p>Últimos 90 dias: 52 ganhos, 36 perdidos. Taxa de 59%. Ciclo médio: 41 dias nos ganhos, 63 nos perdidos.</p></div></div>
      <div class="grade"><section class="cx k6"><h2>Por que perdemos</h2><div class="barras">${motivos.map(([m, n, c]) => `<div class="l"><span>${m}</span><span class="t"><i style="width:${n / 14 * 100}%;--c:${c === 'mau' ? '#a5503f' : '#b88a35'}"></i></span><b class="dir">${n}</b></div>`).join('')}</div></section>
      <section class="cx k6"><h2>Por que ganhamos</h2><div class="barras">${venc.map(([m, n]) => `<div class="l"><span>${m}</span><span class="t"><i style="width:${n / 18 * 100}%;--c:#3f7a5e"></i></span><b class="dir">${n}</b></div>`).join('')}</div></section>
      ${db.perdas.length ? `<section class="cx k12 rolo"><h2>Perdidos registrados no sistema</h2><table><tbody>${db.perdas.slice().reverse().map((x) => `<tr><td><b>${e(x.conta)}</b></td><td>${e(x.motivo)}</td><td>${e(pessoa(x.dono).nome)}</td><td class="dir">${k$(x.valor)}</td><td>${quando(x.dia)}</td></tr>`).join('')}</tbody></table></section>` : ''}
      <section class="cx k12"><h2>Leitura</h2><p style="margin:0">Quando o decisor não participa da demonstração, a taxa cai de 59% para 22%. O playbook já pede o decisor como critério para sair de "Diagnóstico".</p></section></div>`;
  },
  times() {
    return `<div class="titulo"><div><h1>Times</h1><p>SDRs marcam reuniões; closers fecham. Mês corrente.</p></div></div>
      <div class="grade"><section class="cx k6 rolo"><h2>SDRs</h2><table><thead><tr><th>Pessoa</th><th class="dir">Toques</th><th class="dir">Reuniões</th><th class="dir">Compareceram</th></tr></thead><tbody>${[['Bruna', 812, 34, 0.82], ['Igor', 655, 21, 0.71], ['Nathalia', 704, 27, 0.78]].map(([n, t, r, s]) => `<tr><td>${n}</td><td class="dir">${t}</td><td class="dir">${r}</td><td class="dir">${Math.round(s * 100)}%</td></tr>`).join('')}</tbody></table></section>
      <section class="cx k6 rolo"><h2>Closers</h2><table><thead><tr><th>Pessoa</th><th class="dir">Reuniões</th><th class="dir">Ganhos</th><th class="dir">Receita</th></tr></thead><tbody>${[['Fernando', 28, 9, 286000], ['Mariana', 31, 12, 154000], ['Otávio', 23, 6, 72000]].map(([n, r, g, v]) => `<tr><td>${n}</td><td class="dir">${r}</td><td class="dir">${g} (${Math.round(g / r * 100)}%)</td><td class="dir">${k$(v)}</td></tr>`).join('')}</tbody></table></section>
      <section class="cx k12 rolo"><h2>Cota e comissão do trimestre <small>· acima da cota a comissão vale ${String(db.acel).replace('.', ',')}× (acelerador)</small></h2><table><thead><tr><th>Closer</th><th class="dir">Cota (R$)</th><th class="dir">Ganho</th><th style="width:24%">Atingimento</th><th class="dir">Comissão (%)</th><th class="dir">A receber</th></tr></thead><tbody>${closers().map((p) => `<tr><td><b>${e(p.nome)}</b><br><small style="color:var(--tx-3)">${e(p.area)}</small></td><td class="dir"><input class="peso" style="width:110px" data-cota="${p.id}" inputmode="decimal" value="${p.cota}" aria-label="Cota de ${e(p.nome)}"></td><td class="dir">${k$(p.ganho)}</td><td><div class="barras"><div class="l" style="grid-template-columns:1fr 50px"><span class="t"><i style="width:${Math.min(100, p.ganho / (p.cota || 1) * 100)}%;--c:${p.ganho >= p.cota ? '#3f7a5e' : '#215a60'}"></i></span><b class="dir">${Math.round(p.ganho / (p.cota || 1) * 100)}%</b></div></div></td><td class="dir"><input class="peso" data-com="${p.id}" type="number" min="0" max="30" step="0.5" value="${p.com}" aria-label="Comissão de ${e(p.nome)}"></td><td class="dir"><b>${R$(comissao(p))}</b></td></tr>`).join('')}</tbody></table><label class="cp" style="max-width:260px;margin-top:10px">Acelerador acima da cota (×)<input data-acel inputmode="decimal" value="${String(db.acel).replace('.', ',')}"></label></section></div>`;
  },
  playbook() {
    const et = [['Diagnóstico', ['Dor confirmada pelo cliente', 'Decisor identificado e convidado', 'Orçamento aproximado conhecido']], ['Demonstração', ['Decisor presente', 'Casos de uso do cliente mostrados', 'Próximo passo com data']], ['Proposta', ['Escopo aprovado por e-mail', 'Concorrentes mapeados', 'Prazo de decisão definido']], ['Negociação', ['Jurídico do cliente envolvido', 'Condição comercial dentro da alçada']]];
    const obj = [['"Está caro"', 'Mostre o custo de não resolver: horas da equipe por mês × salário. Ofereça começar com um módulo.'], ['"Já usamos o Contaflux"', 'Pergunte o que falta nele. Nossa integração com o ERP ganha 18 em cada 52 vendas.'], ['"Agora não é o momento"', 'Combine uma data e mande o estudo de retorno até lá. Deixe na cadência de nutrição.']];
    return `<div class="titulo"><div><h1>Playbook</h1><p>O que precisa ser verdade para o negócio mudar de fase, e como responder às objeções mais comuns.</p></div></div>
      <div class="grade">${et.map(([n, c]) => `<section class="cx k3"><h2>${n}</h2><ul class="check">${c.map((x) => `<li>${x}</li>`).join('')}</ul></section>`).join('')}
      <section class="cx k12"><h2>Objeções</h2><table><tbody>${obj.map(([o, r]) => `<tr><td style="width:28%"><b>${o}</b></td><td>${r}</td></tr>`).join('')}</tbody></table></section></div>`;
  },
  auditoria() { return `<div class="titulo"><div><h1>Auditoria</h1><p>Mudanças de categoria, regras, distribuição e descontos: quem, quando e o quê.</p></div></div><section class="cx rolo"><table><thead><tr><th>Quando</th><th>Quem</th><th>O quê</th></tr></thead><tbody>${db.audit.map((a) => `<tr><td class="mn">${e(a.q)}</td><td>${e(a.quem)}</td><td>${e(a.o)}</td></tr>`).join('')}</tbody></table></section>`; },
  equipe() {
    const pr = db.plano === 'pro' ? 289 : 229;
    return `<div class="titulo"><div><h1>Equipe</h1><p>Painel do dono: papéis, áreas e quem vê o quê.</p></div></div>
      <div class="grade"><section class="cx k7 rolo"><table><thead><tr><th>Pessoa</th><th>Papel</th><th>Área</th><th>Vê</th></tr></thead><tbody>${db.pessoas.map((p) => `<tr><td><b>${e(p.nome)}</b></td><td>${p.papel}</td><td>${e(p.area)}</td><td>${p.papel === 'SDR' ? 'leads e cadências dela' : 'os próprios negócios e a previsão dele'}</td></tr>`).join('')}<tr><td><b>Você</b></td><td>Diretor</td><td>tudo</td><td>tudo, inclusive mudar a meta</td></tr></tbody></table></section>
      <section class="cx k5"><h2>Plano</h2><p>Assinatura · <b>${R$(pr)}/mês</b></p><div class="bar"><button class="bt ${db.plano === 'basico' ? 'p' : ''}" data-a="plano" data-v="basico">Assinatura · R$ 229/mês</button></div><p style="color:var(--tx-3);font-size:.85rem">Equipe sem limite, histórico de quem fez o quê e até 10 empresas. Anual com 20% a menos. Sem fidelidade.</p></section></div>`;
  },
  ajustes() { return `<div class="titulo"><div><h1>Ajustes</h1></div></div><section class="cx" style="max-width:640px"><label class="cp">Empresa<input data-aj="empresa" value="${e(db.empresa)}"></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Meta do trimestre (R$)<input data-aj="meta" inputmode="decimal" value="${db.meta}"></label><label class="cp">Realizado até hoje (R$)<input data-aj="realizado" inputmode="decimal" value="${db.realizado}"></label></div><p style="color:var(--tx-3);font-size:.86rem">Na versão contratada: discador e gravação de ligações, e-mail e WhatsApp oficial nas cadências, formulários do site, LinkedIn e integração com o ERP (algumas têm custo à parte).</p></section>`; },
};

function formDeal(d) {
  form(d ? `Editar · ${e(d.conta)}` : 'Novo negócio', `<label class="cp">Conta<input name="c" required list="contas-l" value="${d ? e(d.conta) : ''}"><datalist id="contas-l">${db.contas.map((c) => `<option value="${e(c.nome)}">`).join('')}</datalist></label><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px"><label class="cp">Valor (R$)<input name="v" inputmode="decimal" required value="${d ? d.valor : ''}"></label><label class="cp">Mês<select name="m">${['out', 'nov', 'dez'].map((x) => `<option ${d && d.mes === x ? 'selected' : ''}>${x}</option>`).join('')}</select></label><label class="cp">Chance (%)<input name="p" type="number" min="0" max="100" value="${d ? d.prob : 30}"></label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Closer<select name="o">${closers().map((p) => `<option value="${p.id}" ${d && d.dono === p.id ? 'selected' : ''}>${e(p.nome)}</option>`).join('')}</select></label><label class="cp">Categoria<select name="k">${[['pipeline', 'pipeline'], ['melhor', 'melhor caso'], ['commit', 'commit']].map(([v, t]) => `<option value="${v}" ${d && d.cat === v ? 'selected' : ''}>${t}</option>`).join('')}</select></label></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="cp">Próximo passo em (dias)<input name="x" type="number" min="0" value="${d && d.prox != null ? Math.max(0, d.prox) : 2}"></label><label class="cp">Fechamento em (dias)<input name="f" type="number" min="0" value="${d ? Math.max(0, d.fecha ?? 30) : 30}"></label></div><label class="cp">Concorrente na disputa<select name="z"><option value="">nenhum</option>${(db.concorrentes || []).map((c) => `<option ${d && d.conc === c.nome ? 'selected' : ''}>${e(c.nome)}</option>`).join('')}</select></label>`, d ? 'Salvar' : 'Criar', (f) => {
    const v = nv(f.get('v')), p = Number(f.get('p')), k = f.get('k'), conta = String(f.get('c')).trim();
    if (!(v > 0)) return 'Informe o valor.'; if (!(p >= 0 && p <= 100)) return 'Chance entre 0 e 100%.';
    if (k === 'commit' && p < 60) return 'Commit com menos de 60% de chance não é commit: ajuste a chance ou a categoria.';
    if (!d && db.deals.some((y) => sa(y.conta) === sa(conta))) return 'Já existe um negócio com essa conta.';
    const dados = { conta, valor: v, mes: f.get('m'), prob: p, dono: f.get('o'), cat: k, prox: Math.max(0, Math.round(Number(f.get('x')) || 0)), fecha: Math.max(0, Math.round(Number(f.get('f')) || 0)), conc: f.get('z') || '' };
    if (d) { const OM = ['out', 'nov', 'dez']; if (OM.indexOf(dados.mes) > OM.indexOf(d.mes)) { d.empurrado = (d.empurrado || 0) + 1; d.mesOrig ??= d.mes; } regist(`editou ${d.conta}${d.valor !== v ? ` (${k$(d.valor)} → ${k$(v)})` : ''}${d.cat !== k ? `, ${d.cat} → ${k}` : ''}`); Object.assign(d, dados); } else { db.deals.push({ id: uid(), ...dados, parado: 0 }); regist(`criou o negócio ${conta} (${k$(v)})`); }
  });
}
function render() {
  const r = location.hash.slice(1) || 'previsao', n = { pontuacao: db.leads.filter((l) => l.st !== 'closer' && pontos(l) >= db.corte).length, distribuicao: db.novos.filter((x) => !x.para).length, cadencias: db.fila.filter((f) => !f.feito).length, higiene: db.deals.filter((d) => problemas(d).length).length, descontos: db.descontos.filter((x) => x.st === 'pendente').length, renovacoes: db.base.filter((x) => x.saude === 'vermelho' || x.renova < 0).length };
  $('#trilhos').innerHTML = MOD.map(([k, t]) => `<a href="#${k}" ${k === r ? 'aria-current="page"' : ''}>${t}${n[k] ? `<span class="n">${n[k]}</span>` : ''}</a>`).join('');
  $('#area').innerHTML = (M[r] || M.previsao)();
  $('#empresa').textContent = db.empresa; $('#periodo').textContent = `4º trimestre · semana 7 de 13`;
  document.title = `${(MOD.find(([k]) => k === r) || MOD[0])[1]} · Veltria CRM Avançado`;
}
