const ACOES_P = [...MOD.map(([k, t]) => ({ t: `Ir para ${t}`, d: 'módulo', f: () => { location.hash = `#${k}`; } })), { t: 'Distribuir os leads novos', d: 'ação', f: () => A.distribuir() }, { t: 'Passar leads quentes para closers', d: 'ação', f: () => { db.leads.filter((l) => l.st !== 'closer' && pontos(l) >= db.corte).forEach((l) => { l.st = 'closer'; }); regist('passou os leads quentes para closers'); guarda(); render(); toque('Leads quentes entregues aos closers.'); } }, { t: 'Baixar a planilha da previsão', d: 'ação', f: () => A.exportar() }, { t: 'Novo negócio', d: 'ação', f: () => A['novo-deal']() }, { t: 'Fechar a semana (foto da previsão)', d: 'ação', f: () => A.foto() }, { t: 'Pedir desconto', d: 'ação', f: () => A['pedir-desc']() }];
