const MEDDIC = [['m', 'Métricas', 'o ganho em número que o cliente espera'], ['e', 'Decisor econômico', 'quem assina falou com a gente'], ['c1', 'Critérios', 'como ele vai escolher'], ['p', 'Processo de decisão', 'etapas, prazos e quem aprova'], ['i', 'Dor', 'o problema que custa dinheiro hoje'], ['c2', 'Campeão', 'alguém dentro defende a compra']];
function meddic(d) { return MEDDIC.filter(([k]) => d.med?.[k]).length; }
const ONB = [['kickoff', 'Reunião de início'], ['acesso', 'Acessos criados'], ['dados', 'Dados migrados'], ['treino', 'Equipe treinada'], ['golive', 'Em uso (go-live)']];
const pc = (x) => `${Math.round(x * 100)}%`;
/** Teste de duas proporções: z e se a diferença é significativa a 95% (|z| ≥ 1,96). */
function abSig(a, b) { const p1 = a.resp / a.env, p2 = b.resp / b.env, p = (a.resp + b.resp) / (a.env + b.env), se = Math.sqrt(p * (1 - p) * (1 / a.env + 1 / b.env)), z = se ? (p2 - p1) / se : 0; return { p1, p2, z, sig: Math.abs(z) >= 1.96, vence: Math.abs(z) >= 1.96 ? (z > 0 ? 'b' : 'a') : null }; }
/** Cotação: módulos por mês + usuários; 24 meses dão 5% e 36 meses 10% de desconto automático; o desconto extra acima da alçada vai para aprovação. */
function cotar({ mods, usuarios, meses, extra }) {
  const lista = db.modulos.filter(([k]) => mods.includes(k)); if (!lista.length) throw new Error('Escolha pelo menos um módulo.'); if (!(usuarios >= 1 && usuarios <= 5000)) throw new Error('Usuários de 1 a 5.000.'); if (![12, 24, 36].includes(meses)) throw new Error('Contrato de 12, 24 ou 36 meses.'); if (!(extra >= 0 && extra <= 40)) throw new Error('Desconto extra de 0 a 40%.');
  const cheio = lista.reduce((s, [, , v]) => s + v, 0) + usuarios * db.porUsuario, vol = meses === 36 ? 10 : meses === 24 ? 5 : 0, mensal = Math.round(cheio * (1 - vol / 100) * (1 - extra / 100));
  return { cheio, vol, mensal, acv: mensal * 12, tcv: mensal * meses, aprovar: extra > db.alcada };
}
let cot = { mods: ['fin', 'fis'], usuarios: 25, meses: 24, extra: 0 };
