    <section class="cx k5 rolo"><h2>Negócios empurrados <small>· mudaram para um mês depois</small></h2><table><tbody>${emp.map((d) => `<tr><td><b>${e(d.conta)}</b><br><small style="color:var(--tx-3)">${e(pessoa(d.dono).nome)} · era ${d.mesOrig}, agora ${d.mes}</small></td><td class="dir">${k$(d.valor)}</td><td><span class="tag ${d.empurrado >= 2 ? 'mau' : 'at'}">${d.empurrado}×</span></td></tr>`).join('') || '<tr><td>Nenhum negócio empurrado.</td></tr>'}</tbody></table><p style="color:var(--tx-3);font-size:.85rem;margin:8px 0 0">Empurrado duas vezes raramente fecha no trimestre: tire do commit.</p></section>
