function resumoSemana() { const c = soma('commit'), m = soma('melhor'), prob = db.deals.filter((d) => problemas(d).length), emp = db.deals.filter((d) => d.empurrado), desc = db.descontos.filter((x) => x.st === 'pendente'), risco = db.base.filter((b) => b.saude === 'vermelho');
  return [`${db.empresa} · semana ${semanaAtual} de ${SEMANAS}`, `Realizado ${k$(db.realizado)} (${Math.round(db.realizado / db.meta * 100)}% da meta de ${k$(db.meta)}).`, `Com commit: ${k$(db.realizado + c)}. Com melhor caso: ${k$(db.realizado + c + m)}.`, `Pipeline com problema: ${prob.length} negócio(s), ${k$(prob.reduce((s, d) => s + d.valor, 0))}.`, emp.length ? `Empurrados: ${emp.map((d) => d.conta).join(', ')}.` : 'Nenhum negócio empurrado.', desc.length ? `Descontos esperando aprovação: ${desc.map((x) => `${x.conta} ${x.pct}%`).join(', ')}.` : '', risco.length ? `Clientes da base em risco: ${risco.map((b) => b.conta).join(', ')}.` : ''].filter(Boolean).join('\n'); }
// Higiene: limite de dias parado ajustável
