  if ('acel' in d) { const v = nv(t.value); if (!(v >= 1 && v <= 3)) { toque('Acelerador entre 1 e 3.'); render(); return; } db.acel = v; regist(`mudou o acelerador para ${v}×`); guarda(); render(); }
